ch02-play-compare.solution_code:
use std::cmp::Ordering;

fn main() {
    let secret_number: u32 = 38;
    let typed = String::from("38\n");

    let guess: u32 = typed.trim().parse().expect("Please type a number!");
    println!("You guessed: {guess}");

    match guess.cmp(&secret_number) {
        Ordering::Less => println!("Too small!"),
        Ordering::Greater => println!("Too big!"),
        Ordering::Equal => println!("You win!"),
    }
}

ch02-play-loop.solution_code:
use std::cmp::Ordering;

fn main() {
    let secret_number: u32 = 61;
    let inputs = ["oops", "10", "80", "61", "99"];

    for typed in inputs {
        let guess: u32 = match typed.trim().parse() {
            Ok(num) => num,
            Err(_) => {
                println!("Please type a number!");
                continue;
            }
        };

        println!("You guessed: {guess}");

        match guess.cmp(&secret_number) {
            Ordering::Less => println!("Too small!"),
            Ordering::Greater => println!("Too big!"),
            Ordering::Equal => {
                println!("You win!");
                break;
            }
        }
    }
}

