ch03-play-break-value.solution_code:
fn main() {
    let mut n = 0;
    let first = loop {
        n += 1;
        if n * n > 500 {
            break n * n;
        }
    };
    println!("first square over 500: {first}");
}

ch03-play-celsius.solution_code:
fn to_fahrenheit(c: f64) -> f64 {
    c * 9.0 / 5.0 + 32.0
}

fn main() {
    for c in [100.0, -40.0] {
        println!("{c}°C is {}°F", to_fahrenheit(c));
    }
}

ch03-play-const.solution_code:
const SECONDS_PER_MINUTE: u32 = 60;
const MINUTES_PER_HOUR: u32 = 60;

fn main() {
    let minutes: u32 = 5;
    let seconds = minutes * SECONDS_PER_MINUTE;
    println!("{minutes} minutes = {seconds} seconds");
    let hours: u32 = 2;
    let seconds = hours * MINUTES_PER_HOUR * SECONDS_PER_MINUTE;
    println!("{hours} hours = {seconds} seconds");
}

ch03-play-fizzbuzz.solution_code:
fn main() {
    for n in 1..=15 {
        if n % 15 == 0 {
            println!("FizzBuzz");
        } else if n % 3 == 0 {
            println!("Fizz");
        } else if n % 5 == 0 {
            println!("Buzz");
        } else {
            println!("{n}");
        }
    }
}

