ch03-play-tuple.solution_code:
fn divide(a: u32, b: u32) -> (u32, u32) {
    (a / b, a % b)
}

fn main() {
    let (q, r) = divide(17, 5);
    println!("17 / 5 = {q} remainder {r}");
}
